import { describe, test, expect } from "bun:test";
import { gorillaPass, chooseCell, blastSurface, type CellTopology } from "../src/index.ts";
import { mulberry32 } from "@army/simian";

const TOPO: CellTopology = {
	cells: [
		{ id: "cell-a", members: ["gw-1", "gw-2"] },
		{ id: "cell-b", members: ["gw-3", "db", "cache"] },
		{ id: "control", members: ["coordinator"], critical: true },
	],
};

describe("gorilla: wholesale cell loss", () => {
	test("p>=1 always takes down a NON-critical cell", () => {
		const d = gorillaPass(TOPO, { probability: 1 }, { rng: mulberry32(5) });
		expect(d.cell).not.toBeNull();
		expect(d.down.length).toBeGreaterThan(0);
		// never the control plane (critical is optional; assert by exclusion)
		expect(d.cell!.id).not.toBe("control");
		expect(d.down).not.toContain("coordinator");
		expect(d.down).toContain(d.cell!.members[0]);
	});

	test("cell members are the blast surface of a whole-cell outage", () => {
		const d = gorillaPass(TOPO, { probability: 1 }, { rng: mulberry32(9) });
		const surface = blastSurface(TOPO);
		expect(surface).not.toContain("coordinator");
		expect(d.down.every(m => surface.includes(m))).toBe(true);
	});

	test("p=0 → gorilla naps, reports empty loss with reason", () => {
		const d = gorillaPass(TOPO, { probability: 0 }, { rng: mulberry32(2) });
		expect(d.cell).toBeNull();
		expect(d.down).toEqual([]);
		expect(d.reason).toMatch(/napping/);
	});

	test("deterministic under fixed seed", () => {
		const a = gorillaPass(TOPO, { probability: 0.5 }, { rng: mulberry32(77) });
		const b = gorillaPass(TOPO, { probability: 0.5 }, { rng: mulberry32(77) });
		expect(a.cell?.id).toBe(b.cell?.id);
		expect(a.down).toEqual(b.down);
	});

	test("chooseCell on single-cell topology returns that cell", () => {
		const single: CellTopology = { cells: [{ id: "only", members: ["x"] }] };
		expect(chooseCell(single, mulberry32(1)).id).toBe("only");
	});

	test("empty eligible topology refuses (no non-critical cells)", () => {
		const onlyCritical: CellTopology = { cells: [{ id: "ctrl", members: ["c"], critical: true }] };
		expect(() => chooseCell(onlyCritical, mulberry32(1))).toThrow(/no eligible/);
	});
});